"use client"

import { Settings01 } from "@/registry/blocks/settings-01/settings-01"

/**
 * 设置页入口：用 onSave 把设置存到你自己的后端。
 * 回调返回 Promise；失败时 throw new Error("中文原因")，原因会显示在底部保存栏上。
 * 想把改动实时应用到页面（例如切换主题），在 onValueChange 里处理。
 */
export default function SettingsPage() {
  return (
    <Settings01
      onSave={async (values) => {
        // TODO: 调用你的接口，例如 await fetch("/api/settings", { method: "PUT", body: JSON.stringify(values) })
        console.info("save settings", values)
        await new Promise((resolve) => setTimeout(resolve, 600))
      }}
    />
  )
}

"use client"

import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Check, LoaderCircle, Settings } from "lucide-react"
import { useMemo, useState, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/registry/hooks/use-controllable-state"
import { flowToneStyle } from "@/registry/lib/flow-tone"

import { AppearanceSection } from "./appearance-section"
import {
  DEFAULT_VALUES,
  SECTION_IDS,
  SECTION_KEYS,
  formatLabel,
  resolveLabels,
  type Settings01Labels,
} from "./config"
import { EditorSection } from "./editor-section"
import { NotificationsSection } from "./notifications-section"
import { PrivacySection } from "./privacy-section"
import type { SectionProps, SetValue } from "./section-layout"
import { SectionNav, SectionTabs } from "./section-nav"
import { SoundSection } from "./sound-section"
import type { Settings01SectionId, Settings01Values } from "./types"
import { useSaveAction } from "./use-save-action"
import { isSameValue } from "./utils"

const SECTIONS: Record<
  Settings01SectionId,
  (props: SectionProps) => ReactNode
> = {
  appearance: AppearanceSection,
  notifications: NotificationsSection,
  sound: SoundSection,
  editor: EditorSection,
  privacy: PrivacySection,
}

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))
// 未传回调时的示例实现：只在控制台打印，并模拟 0.8 秒的网络请求
async function demoSave(values: Settings01Values) {
  console.info("[settings-01] onSave", values)
  await wait(800)
}

function pickKeys(
  values: Settings01Values,
  keys: readonly (keyof Settings01Values)[],
) {
  return Object.fromEntries(keys.map((key) => [key, values[key]]))
}

/**
 * 设置页：左侧分区导航（窄屏变成顶部分段选择）+ 右侧当前分区的控制面板 + 底部保存栏。
 * 值同时支持受控与非受控；保存回调返回 Promise，组件管理 loading，回调 throw 的 Error.message 会显示在保存栏上。
 */
function Settings01({
  value: valueProp,
  defaultValue,
  defaults,
  onValueChange,
  section: sectionProp,
  defaultSection = "appearance",
  onSectionChange,
  onSave = demoSave,
  labels,
  className,
}: {
  /** 受控的全部设置值 */
  value?: Settings01Values
  /** 非受控时的初始值，没写的项取 `defaults` */
  defaultValue?: Partial<Settings01Values>
  /** 出厂默认值，逐项覆盖 config.ts 的 DEFAULT_VALUES；「已修改」「恢复默认」都以它为准 */
  defaults?: Partial<Settings01Values>
  /** 任何一项变化时回调，参数是变化后的全部设置 */
  onValueChange?: (value: Settings01Values) => void
  /** 受控的当前分区 */
  section?: Settings01SectionId
  defaultSection?: Settings01SectionId
  onSectionChange?: (section: Settings01SectionId) => void
  /** 点击「保存」时调用；失败时 throw new Error("原因")，原因会显示在保存栏 */
  onSave?: (values: Settings01Values) => Promise<void>
  /** 覆盖默认文案，见 config.ts 的 DEFAULT_LABELS */
  labels?: Partial<Settings01Labels>
  className?: string
}) {
  const text = resolveLabels(labels)
  const reducedMotion = useReducedMotion()
  const resolvedDefaults = useMemo<Settings01Values>(
    () => ({ ...DEFAULT_VALUES, ...defaults }),
    [defaults],
  )
  const [values, setValues] = useControllableState<Settings01Values>({
    prop: valueProp,
    defaultProp: { ...resolvedDefaults, ...defaultValue },
    onChange: onValueChange,
  })
  const [section, setSection] = useControllableState<Settings01SectionId>({
    prop: sectionProp,
    defaultProp: defaultSection,
    onChange: onSectionChange,
  })
  // 上一次保存（或首次载入）时的值：和默认值比出「已修改」，和它比出「有未保存的更改」
  const [saved, setSaved] = useState(values)
  const action = useSaveAction(text.saveFailed)

  const set: SetValue = (key, next) => {
    setValues((previous) => ({ ...previous, [key]: next }))
    action.reset()
  }
  const modified = (key: keyof Settings01Values) =>
    !isSameValue(values[key], resolvedDefaults[key])
  const counts = Object.fromEntries(
    SECTION_IDS.map((id) => [id, SECTION_KEYS[id].filter(modified).length]),
  ) as Record<Settings01SectionId, number>
  const total = SECTION_IDS.reduce((sum, id) => sum + counts[id], 0)
  const dirty = (Object.keys(values) as (keyof Settings01Values)[]).some(
    (key) => !isSameValue(values[key], saved[key]),
  )
  const pending = action.status === "pending"

  const resetSection = (id: Settings01SectionId) => {
    setValues((previous) => ({
      ...previous,
      ...pickKeys(resolvedDefaults, SECTION_KEYS[id]),
    }))
    action.reset()
  }
  const resetAll = () => {
    setValues({ ...resolvedDefaults })
    action.reset()
  }
  const save = async () => {
    const snapshot = values
    if (await action.run(() => onSave(snapshot))) setSaved(snapshot)
  }

  const Section = SECTIONS[section]
  const sectionProps: SectionProps = {
    values,
    labels: text,
    set,
    modified,
    count: counts[section],
    onReset: () => resetSection(section),
    getCode: () =>
      JSON.stringify(pickKeys(values, SECTION_KEYS[section]), null, 2),
  }

  return (
    <div
      data-slot="settings-01"
      className={cn(
        "relative flex min-h-svh flex-col bg-background text-foreground",
        className,
      )}
      // 强调色同时作为 --flow-tone，导航的选中标记等跟着它走
      style={flowToneStyle(values.accent)}
    >
      <header className="border-b border-edge">
        <div className="mx-auto flex w-full max-w-6xl items-center gap-3 px-4 py-4 sm:px-6 lg:border-x lg:border-edge">
          <span
            aria-hidden="true"
            className="flex size-8 shrink-0 items-center justify-center rounded-md border border-edge bg-muted/50"
          >
            <Settings className="size-4" />
          </span>
          <div className="min-w-0">
            <h1 className="text-base leading-tight font-semibold tracking-tight">
              {text.title}
            </h1>
            <p className="truncate text-xs text-muted-foreground">
              {text.description}
            </p>
          </div>
        </div>
      </header>

      <div className="mx-auto flex w-full max-w-6xl flex-1 flex-col md:flex-row lg:border-x lg:border-edge">
        <SectionNav
          section={section}
          onSectionChange={setSection}
          counts={counts}
          labels={text}
        />
        <SectionTabs
          section={section}
          onSectionChange={setSection}
          labels={text}
          tone={values.accent}
        />
        <main className="min-w-0 flex-1 p-4 sm:p-6">
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={section}
              initial={{ opacity: 0, y: reducedMotion ? 0 : 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: reducedMotion ? 0 : -8 }}
              transition={{ duration: 0.18 }}
            >
              <Section {...sectionProps} />
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <footer
        aria-label={text.footerLabel}
        data-slot="settings-01-footer"
        className="sticky bottom-0 z-20 border-t border-edge bg-background/90 backdrop-blur"
      >
        <div className="mx-auto flex w-full max-w-6xl items-center justify-between gap-3 px-4 py-3 sm:px-6 lg:border-x lg:border-edge">
          <div className="min-w-0 text-sm">
            <p className="truncate font-medium tabular-nums">
              {total > 0
                ? formatLabel(text.modifiedCount, { count: total })
                : text.unmodified}
            </p>
            {/* 状态行固定占一行高度，避免保存时底栏跳动；出错时同一位置换成红色的错误原因 */}
            {action.status === "error" ? (
              <p
                role="alert"
                data-slot="settings-01-error"
                className="min-h-4 truncate text-xs text-destructive"
              >
                {action.error}
              </p>
            ) : (
              <p
                role="status"
                data-slot="settings-01-status"
                className="flex min-h-4 items-center gap-1 truncate text-xs text-muted-foreground"
              >
                {pending ? (
                  text.saving
                ) : action.status === "saved" ? (
                  <>
                    <Check className="size-3.5 shrink-0" />
                    {text.saved}
                  </>
                ) : dirty ? (
                  text.unsaved
                ) : (
                  text.upToDate
                )}
              </p>
            )}
          </div>
          <div className="flex shrink-0 items-center gap-2">
            <Button
              variant="outline"
              disabled={total === 0 || pending}
              onClick={resetAll}
            >
              {text.resetAll}
            </Button>
            <Button disabled={!dirty || pending} onClick={save}>
              {pending ? (
                <LoaderCircle className="animate-spin" data-icon="inline-start" />
              ) : null}
              {pending ? text.saving : text.save}
            </Button>
          </div>
        </div>
      </footer>
    </div>
  )
}

export { Settings01 }
export type { Settings01Labels, Settings01SectionId, Settings01Values }

import { DEFAULT_LABELS } from "./config"

/** 两个设置值是否相同；区间（数组）逐项比较。 */
function isSameValue(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b))
    return a.length === b.length && a.every((item, index) => item === b[index])
  return Object.is(a, b)
}

/**
 * 把小时数格式化成「22:00」。
 * 免打扰滑块的范围是 12–36（跨午夜），所以先对 24 取模；用 Intl 并固定 UTC，保证服务端与客户端一致。
 */
function formatHour(hour: number, locale: string = "zh-CN"): string {
  const whole = Math.floor(hour)
  const minutes = Math.round((hour - whole) * 60)
  return new Intl.DateTimeFormat(locale, {
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(1970, 0, 1, whole % 24, minutes)))
}

/** 把未知错误转成可展示的文案；没有 message 时用兜底文案。 */
function errorMessage(
  error: unknown,
  fallback: string = DEFAULT_LABELS.saveFailed,
) {
  return error instanceof Error && error.message ? error.message : fallback
}

export { errorMessage, formatHour, isSameValue }

import type * as React from "react"
import { useId } from "react"

import { cn } from "@/lib/utils"
import {
  ControlPanel,
  ControlPanelActions,
  ControlPanelCopy,
  ControlPanelHeader,
  ControlPanelReset,
  ControlPanelTitle,
} from "@/registry/ui/control-panel/control-panel"

import {
  SECTION_LABEL_KEYS,
  formatLabel,
  type Settings01Labels,
} from "./config"
import type { Settings01SectionId, Settings01Values } from "./types"

type SetValue = <Key extends keyof Settings01Values>(
  key: Key,
  value: Settings01Values[Key],
) => void

/** 每个分区组件收到的同一组属性 */
type SectionProps = {
  values: Settings01Values
  labels: Settings01Labels
  set: SetValue
  /** 某一项是否与默认值不同，传给控件的 `modified` */
  modified: (key: keyof Settings01Values) => boolean
  /** 本分区有几项不是默认值 */
  count: number
  /** 把本分区恢复为默认值 */
  onReset: () => void
  /** 本分区当前取值的 JSON，复制按钮用 */
  getCode: () => string
}

/**
 * 分区外壳：标题与说明 + 控制面板（头部显示本分区已修改项数，带复制与恢复）。
 * 有 `aside` 时在宽屏放到右侧，窄屏排在面板上方。
 */
function SectionLayout({
  id,
  labels,
  count,
  onReset,
  getCode,
  aside,
  children,
}: Pick<SectionProps, "labels" | "count" | "onReset" | "getCode"> & {
  id: Settings01SectionId
  aside?: React.ReactNode
  children: React.ReactNode
}) {
  const headingId = useId()
  const keys = SECTION_LABEL_KEYS[id]
  return (
    <section
      id={`settings-01-${id}`}
      aria-labelledby={headingId}
      data-slot="settings-01-section"
      data-section={id}
      className="flex flex-col gap-4"
    >
      <header>
        <h2
          id={headingId}
          className="text-base font-semibold tracking-tight"
        >
          {labels[keys.title]}
        </h2>
        <p className="mt-1 text-sm leading-6 text-muted-foreground">
          {labels[keys.description]}
        </p>
      </header>
      <div
        className={cn(
          "grid items-start gap-6",
          aside && "lg:grid-cols-[minmax(0,1fr)_16rem]",
        )}
      >
        <ControlPanel className={cn("max-w-2xl", aside && "lg:max-w-none")}>
          <ControlPanelHeader>
            <ControlPanelTitle>
              {count > 0
                ? formatLabel(labels.panelModified, { count })
                : labels.panelDefault}
            </ControlPanelTitle>
            <ControlPanelActions>
              <ControlPanelCopy
                code={getCode}
                label={labels.copySection}
                copiedLabel={labels.copiedSection}
              />
              <ControlPanelReset
                label={labels.resetSection}
                disabled={count === 0}
                onClick={onReset}
              />
            </ControlPanelActions>
          </ControlPanelHeader>
          {children}
        </ControlPanel>
        {aside ? (
          <div
            data-slot="settings-01-aside"
            className="order-first lg:sticky lg:top-6 lg:order-none"
          >
            {aside}
          </div>
        ) : null}
      </div>
    </section>
  )
}

export { SectionLayout }
export type { SectionProps, SetValue }

import type * as React from "react"
import { Bell, Code, Palette, ShieldCheck, Volume2 } from "lucide-react"

import { SegmentedControl } from "@/registry/ui/segmented-control/segmented-control"

import {
  SECTION_IDS,
  SECTION_LABEL_KEYS,
  formatLabel,
  type Settings01Labels,
} from "./config"
import type { Settings01SectionId } from "./types"

const SECTION_ICONS: Record<
  Settings01SectionId,
  React.ComponentType<{ className?: string }>
> = {
  appearance: Palette,
  notifications: Bell,
  sound: Volume2,
  editor: Code,
  privacy: ShieldCheck,
}

/** 宽屏左侧的分区导航：一行一个分区，右侧小圆标显示该分区已修改的项数。 */
function SectionNav({
  section,
  onSectionChange,
  counts,
  labels,
}: {
  section: Settings01SectionId
  onSectionChange: (section: Settings01SectionId) => void
  counts: Record<Settings01SectionId, number>
  labels: Settings01Labels
}) {
  return (
    <nav
      aria-label={labels.navLabel}
      data-slot="settings-01-nav"
      className="hidden w-52 shrink-0 flex-col border-r border-edge md:flex"
    >
      {SECTION_IDS.map((id) => {
        const Icon = SECTION_ICONS[id]
        const active = id === section
        const count = counts[id]
        return (
          <button
            key={id}
            type="button"
            aria-current={active ? "page" : undefined}
            data-slot="settings-01-nav-item"
            onClick={() => onSectionChange(id)}
            className="relative flex h-10 w-full shrink-0 cursor-pointer items-center gap-2.5 border-b border-edge px-4 text-start text-sm text-muted-foreground outline-none transition-colors before:absolute before:inset-y-0 before:left-0 before:w-0.5 hover:bg-muted/50 hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:ring-inset aria-[current=page]:bg-muted/60 aria-[current=page]:font-medium aria-[current=page]:text-foreground aria-[current=page]:before:bg-(--flow-tone)"
          >
            <Icon className="size-4 shrink-0" />
            <span className="truncate">{labels[SECTION_LABEL_KEYS[id].title]}</span>
            {count > 0 ? (
              <span
                data-slot="settings-01-nav-count"
                title={formatLabel(labels.navSectionModified, { count })}
                className="ms-auto min-w-5 rounded-full bg-foreground/10 px-1.5 text-center text-[11px] leading-5 text-foreground tabular-nums"
              >
                {count}
                <span className="sr-only">
                  {formatLabel(labels.navSectionModified, { count })}
                </span>
              </span>
            ) : null}
          </button>
        )
      })}
    </nav>
  )
}

/** 窄屏顶部的分段选择：用短名，五项刚好排进 375px。 */
function SectionTabs({
  section,
  onSectionChange,
  labels,
  tone,
}: {
  section: Settings01SectionId
  onSectionChange: (section: Settings01SectionId) => void
  labels: Settings01Labels
  tone: string
}) {
  return (
    <div
      data-slot="settings-01-tabs"
      className="border-b border-edge p-4 sm:px-6 md:hidden"
    >
      <SegmentedControl
        aria-label={labels.navLabel}
        tone={tone}
        value={section}
        onValueChange={(next) => onSectionChange(next as Settings01SectionId)}
        options={SECTION_IDS.map((id) => ({
          value: id,
          label: labels[SECTION_LABEL_KEYS[id].nav],
        }))}
      />
    </div>
  )
}

export { SectionNav, SectionTabs }

import type * as React from "react"
import { Monitor, Moon, Sparkles, Sun } from "lucide-react"

import { cn } from "@/lib/utils"
import { flowToneStyle } from "@/registry/lib/flow-tone"

import type { Settings01Labels } from "./config"
import type { Density, Settings01Values, ThemeMode } from "./types"

const DENSITY_CLASSES: Record<Density, string> = {
  compact: "gap-2 p-3",
  comfortable: "gap-3 p-4",
  spacious: "gap-4 p-5",
}

const MODE_ICONS: Record<ThemeMode, React.ComponentType<{ className?: string }>> =
  { light: Sun, dark: Moon, system: Monitor }

/** 预览卡片的外框：标题栏 + 内容区。纯展示，对读屏隐藏。 */
function PreviewFrame({
  title,
  badge,
  dark = false,
  className,
  style,
  children,
}: {
  title: string
  badge?: React.ReactNode
  /** 在卡片内套用深色主题变量 */
  dark?: boolean
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  return (
    <div
      aria-hidden="true"
      data-slot="settings-01-preview"
      className={cn(
        "overflow-hidden rounded-lg border border-edge bg-muted/40 text-foreground",
        dark && "dark bg-background",
        className,
      )}
      style={style}
    >
      <div className="flex h-10 items-center justify-between gap-2 border-b border-edge px-3 text-xs text-muted-foreground">
        <span className="truncate">{title}</span>
        {badge ? (
          <span className="flex shrink-0 items-center gap-1 [&_svg]:size-3.5">
            {badge}
          </span>
        ) : null}
      </div>
      {children}
    </div>
  )
}

/**
 * 外观预览：一张小卡片，随主题模式、强调色、字号、圆角、信息密度和动态效果实时变化。
 * 深色用 `.dark` 变量在卡片内套用；站点本身已是深色时，浅色无法在卡片里反向还原，所以标题栏另外写出当前模式。
 */
function AppearancePreview({
  values,
  labels,
}: {
  values: Settings01Values
  labels: Settings01Labels
}) {
  const ModeIcon = MODE_ICONS[values.theme]
  const modeLabel = {
    light: labels.previewModeLight,
    dark: labels.previewModeDark,
    system: labels.previewModeSystem,
  }[values.theme]
  return (
    <PreviewFrame
      title={labels.previewTitle}
      dark={values.theme === "dark"}
      badge={
        <>
          <ModeIcon />
          {modeLabel}
        </>
      }
      style={
        {
          ...flowToneStyle(values.accent),
          "--preview-radius": `${values.radius}px`,
        } as React.CSSProperties
      }
    >
      <div className="p-3">
        <div
          className={cn(
            "flex flex-col rounded-(--preview-radius) border border-edge bg-background shadow-xs transition-[gap,padding] duration-200 motion-reduce:transition-none",
            DENSITY_CLASSES[values.density],
          )}
          style={{ fontSize: values.fontSize }}
        >
          <div className="flex items-center gap-2.5">
            <span className="flex size-8 shrink-0 items-center justify-center rounded-(--preview-radius) bg-(--flow-tone)/15 text-(--flow-tone)">
              <Sparkles className="size-4" />
            </span>
            <div className="min-w-0 flex-1">
              <p className="truncate text-[1.1em] leading-tight font-medium">
                {labels.previewHeading}
              </p>
              <p className="flex items-center gap-1.5 text-[0.8em] text-muted-foreground">
                <span
                  className={cn(
                    "size-1.5 rounded-full bg-(--flow-tone)",
                    !values.reduceMotion && "animate-pulse motion-reduce:animate-none",
                  )}
                />
                {labels.previewLive}
              </p>
            </div>
          </div>
          <p className="text-[1em] leading-snug text-muted-foreground">
            {labels.previewBody}
          </p>
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center justify-between text-[0.8em] text-muted-foreground">
              <span>{labels.previewProgress}</span>
              <span className="tabular-nums">72%</span>
            </div>
            <div className="h-1.5 overflow-hidden rounded-full bg-muted">
              <div className="h-full w-[72%] rounded-full bg-(--flow-tone)" />
            </div>
          </div>
          {/* 模拟按钮：高度取默认档 32px，圆角跟随预览圆角 */}
          <span className="inline-flex h-8 items-center justify-center self-start rounded-(--preview-radius) border border-(--flow-tone) bg-(--flow-tone)/10 px-3 text-[0.9em] font-medium">
            {labels.previewAction}
          </span>
        </div>
      </div>
    </PreviewFrame>
  )
}

/** 示例代码：level 是嵌套层级 */
const SAMPLE_CODE = [
  { level: 0, text: "function greet(name) {" },
  { level: 1, text: "if (name) {" },
  { level: 2, text: "return `Hi, ${name}`" },
  { level: 1, text: "}" },
  { level: 1, text: 'return "Hi"' },
  { level: 0, text: "}" },
] as const

const INDENT_WIDTH = { "2": 2, "4": 4, tab: 4 } as const

/** 编辑器预览：缩进宽度、行高与空白字符的显示会实时变化。 */
function EditorPreview({
  values,
